{% if doc.select_from == "แบบบันทึกทางการพยาบาลผู้ป่วยรักษาสายตาด้วยเลเซอร์ โรงพยาบาลจักษุสุราษฎร์" %}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Sarabun:ital,wght@0,100;0,200;0,300;0,400;0,500;0,600;0,700;0,800;1,100;1,200;1,300;1,400;1,500;1,600;1,700;1,800&display=swap');

@media screen {
    .print-format {
        max-width: 210mm;
        padding: 0mm;
        min-height: 297mm;
    }
    .print-preview {
        max-width: 210mm;
        padding: 0mm;
        min-height: 297mm;
    }
}

@page {
    size: A4 portrait;
    margin: 0;
}

* {
    font-family: 'Sarabun';
    box-sizing: border-box;
}

.bill {
    background-image: url(/files/page_01_highres.jpg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center center;
    background-size: 100% auto;
    -webkit-print-color-adjust: exact;
    width: 100%;
}

.bill2 {
    background-image: url(/files/page_02_highres.jpg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center center;
    background-size: 100% auto;
    -webkit-print-color-adjust: exact;
    width: 100%;
}



.content-wrapper {
    position: relative;
    height: 100%;
}

.con {
    position: absolute;
    font-size: 11.5px; 
    color: black;
}

</style>



  {% set day = frappe.utils.get_datetime(doc.datee).strftime('%d') %}
  {% set month = frappe.utils.get_datetime(doc.datee).strftime('%m') %}
  {% set y = frappe.utils.get_datetime(doc.datee).strftime('%Y') %}
  {% set thyear = y | int + 543 %}

  {% if month == "01" %}
  {% set thai_month = "มกราคม" %}
  {% elif month == "02" %}
  {% set thai_month = "กุมภาพันธ์" %}
  {% elif month == "03" %}
  {% set thai_month = "มีนาคม" %}
  {% elif month == "04" %}
  {% set thai_month = "เมษายน" %}
  {% elif month == "05" %}
  {% set thai_month = "พฤษภาคม" %}
  {% elif month == "06" %}
  {% set thai_month = "มิถุนายน" %}
  {% elif month == "07" %}
  {% set thai_month = "กรกฎาคม" %}
  {% elif month == "08" %}
  {% set thai_month = "สิงหาคม" %}
  {% elif month == "09" %}
  {% set thai_month = "กันยายน" %}
  {% elif month == "10" %}
  {% set thai_month = "ตุลาคม" %}
  {% elif month == "11" %}
  {% set thai_month = "พฤศจิกายน" %}
  {% elif month == "12" %}
  {% set thai_month = "ธันวาคม" %}
  {% endif %}

<div style="height: 297mm;" class="bill">
    <div class="content-wrapper">
        <div class="con" style="top: 21.5mm; left: 90mm;"> <!--วันที่-->
            {{ day }}/{{ month }}/{{ thyear }} 
        </div>

        <div class="con" style="top: 21.5mm; left: 130mm;">
            {% set time_obj = frappe.utils.get_time(doc.start_time) %}
            {{ "%02d:%02d น." % (time_obj.hour, time_obj.minute) }}
        </div>

        <div class="con" style="top: 21.5mm; left: 172mm;"> <!--End Time-->
            {% set time_obj = frappe.utils.get_time(doc.end_time) %}
            {{ "%02d:%02d น." % (time_obj.hour, time_obj.minute) }}
        </div>

        <div class="con" style="top: 27mm; left: 88mm;"> <!--AN-->
            {{ doc.an }}
        </div>

        {% if doc.ward == "IPD" %}
            <div class="con" style="top: 28mm; left: 131mm;"> <!--IPD-->
                ✔
            </div>
        {% endif %}

        {% if doc.ward == "OPD" %}
            <div class="con" style="top: 28mm; left: 144mm;"> <!--OPD-->
                ✔
            </div>
        {% endif %}

        <div class="con" style="top: 32mm; left: 93mm;"> <!--Dx: Myopia   ช่องในระบบไม่มี-->
            3
        </div>

        {% if doc.treatment_type == "PRK" %}
            <div class="con" style="top: 33mm; left: 108.5mm;"> <!--PRK-->
                ✔
            </div>
        {% endif %}

        {% if doc.treatment_type == "TRANS PRK" %}
