                ✔
            </div>
        {% endif %}

        {% if doc.surgery_type == "Elective" %}
            <div class="con" style="top: 38mm; left: 121.5mm;"> <!--Elective-->
                ✔
            </div>
        {% endif %}

        {% if doc.surgery_type == "Emergency" %}
            <div class="con" style="top: 38mm; left: 144mm;"> <!--Emergency-->
                ✔
            </div>
        {% endif %}

        {% if doc.refusese == 1 %}
