        {% endif %}
        {% endfor %}

        {% for eye_e in doc.eyeeye %}
        {% if eye_e.assessment == "VA" %}
            <div class="con" style="top: 104mm; left: 17mm;"> <!--VA -->
                {{ eye_e.data00 or '' }}
