            <div class="con" style="top: 109mm; left: 50mm;"> <!--c glass -->
                {{ eye_e.data000 or '' }}
            </div>
        {% endif %}

        {% if eye_e.assessment == "Laser satting" %}
        <div class="con" style="top: 114mm; left: 29mm;"> <!--Laser setting -->
            {{ eye_e.data00 or '' }}
        </div>
        <div class="con" style="top: 118mm; left: 29mm;"> <!--Laser setting -->
